import {
	getModifierTextByContext,
	parseConstructibleAdjacencyNameOnly,
} from "#core/ui/utilities/utilities-core-textprovider.js";
import { Icon } from "#core/ui/utilities/utilities-image.js";

import type { TreeGridDepthInfo } from "#base/ui/tree-grid/tree-support.js";
import { ConstructibleHasTagType, getConstructibleTagsFromType } from "#base/ui/utilities/utilities-tags.js";

/** Yield change data for display. */
export interface UnlockYieldChange {
	/** The yield type (e.g., "YIELD_FOOD", "YIELD_PRODUCTION"). */
	yieldType: YieldType;
	/** The amount of yield change. */
	amount: number;
}

/** Adjacency group data for display. */
export interface UnlockAdjacencyGroup {
	/** Unique identifier for keying. */
	id: string;
	/** Localization key for the text. */
	textKey: string;
	/** Arguments for the localization string. */
	args: LocalizedTextArgument[];
	/** Optional list markup for grouped adjacencies. */
	listMarkup?: string;
}

/** A single description line that should be stylized. */
export interface UnlockDescriptionLine {
	/** Localization key or pre-stylized text. */
	text: string;
}

/**
 * Structured description data for an unlock target.
 * This provides all the information needed to render a rich tooltip
 * without pre-composing strings, allowing for reactive L10n component usage.
 */
export interface UnlockTargetDescription {
	/** Target kind (e.g., "KIND_UNIT", "KIND_CONSTRUCTIBLE"). */
	kind: string;
	/** Target type identifier. */
	type: string;
	/** Tags for categorization (e.g., "Modern Military Building"). */
	tags: string[];
	/** Base yield changes (e.g., Food +2, Production +8). */
	yields: UnlockYieldChange[];
	/** Adjacency bonuses grouped by yield type. */
	adjacencies: UnlockAdjacencyGroup[];
	/** Description lines (from modifiers, tooltips, or base description). */
	descriptionLines: UnlockDescriptionLine[];
}

/**
 * Get the localized name for an unlock target.
 * @param targetType - The type identifier of the unlock target.
 * @param targetKind - The kind of the unlock target.
 * @returns The localization key for the name (not pre-composed).
 */
export function getUnlockTargetNameKey(targetType: string, targetKind: string): string {
	if (targetKind === "KIND_MODIFIER") {
		const modInfo = GameInfo.Modifiers.find((o) => o.ModifierId === targetType);
		if (modInfo) {
			const modifierName = getModifierTextByContext(modInfo.ModifierId, "Name");
			return modifierName ?? "";
		}
	}

	if (targetKind === "KIND_CONSTRUCTIBLE") {
		const constructibleInfo = GameInfo.Constructibles.find((o) => o.ConstructibleType === targetType);
		if (constructibleInfo?.Name) {
			return constructibleInfo.Name;
		}
	}

	if (targetKind === "KIND_UNIT") {
		const unitInfo = GameInfo.Units.find((o) => o.UnitType === targetType);
		if (unitInfo?.Name) {
			return unitInfo.Name;
		}
	}

	if (targetKind === "KIND_TRADITION") {
		const traditionInfo = GameInfo.Traditions.find((o) => o.TraditionType === targetType);
		if (traditionInfo?.Name) {
			return traditionInfo.Name;
		}
	}

	if (targetKind === "KIND_DIPLOMATIC_ACTION") {
		const diploActionInfo = GameInfo.DiplomacyActions.find((o) => o.DiplomacyActionType === targetType);
		if (diploActionInfo?.Name) {
			return diploActionInfo.Name;
		}
	}

	if (targetKind === "KIND_PROJECT") {
		const projectInfo = GameInfo.Projects.find((o) => o.ProjectType === targetType);
		if (projectInfo?.Name) {
			return projectInfo.Name;
		}
	}

	// Error case: return the target type as fallback
	return targetType;
}

/**
 * Get the icon URL for an unlock target.
 * @param targetType - The type identifier of the unlock target.
 * @param targetKind - The kind of the unlock target.
 * @returns The icon URL.
 */
export function getUnlockTargetIconUrl(targetType: string, targetKind: string): string {
	// Target is a CONSTRUCTIBLE
	if (targetKind == "KIND_CONSTRUCTIBLE") {
		const constructibleInfo = GameInfo.Constructibles.find((o) => o.ConstructibleType == targetType);
		if (constructibleInfo) {
			return Icon.getConstructibleIconFromDefinition(constructibleInfo);
		}
	}

	// Target is a UNIT
	if (targetKind == "KIND_UNIT") {
		const unitInfo = GameInfo.Units.find((o) => o.UnitType == targetType);
		if (unitInfo) {
			return Icon.getUnitIconFromDefinition(unitInfo);
		}
	}

	// Target is a DIPLOMATIC ACTION
	if (targetKind == "KIND_DIPLOMATIC_ACTION") {
		const actionInfo = GameInfo.DiplomaticProjects_UI_Data.find((o) => o.DiplomacyActionType == targetType);

		let iconURL = UI.getIconURL(targetType);
		if (iconURL != "") {
			return iconURL;
		}

		if (actionInfo) {
			// Setting it up as a switch in case we add more icons for other types of actions in the future.
			switch (actionInfo.DiplomacyActionGroup) {
				case "DIPLOMACY_ACTION_GROUP_ESPIONAGE":
					iconURL = UI.getIcon("MOD_ESPIONAGE_UNLOCK");
					return iconURL;
				default:
					break;
			}
		}

		iconURL = UI.getIcon(targetKind + "_UNLOCK");
		return iconURL;
	}

	// Target is a TRADITION/POLICY
	if (targetKind == "KIND_TRADITION") {
		let iconURL = UI.getIconURL(targetType);
		if (iconURL != "") {
			return iconURL;
		}

		const TraditionInfo = GameInfo.Traditions.find((o) => o.TraditionType == targetType);
		if (TraditionInfo) {
			if (TraditionInfo.CultureSlotType == "TRADITION_CULTURE_SLOT") {
				iconURL = UI.getIcon("KIND_TRADITION_UNLOCK");
				if (iconURL) return iconURL;
			} else {
				iconURL = UI.getIcon("MOD_POLICY_UNLOCK");
				if (iconURL) return iconURL;
			}
		}
	}

	let iconURL = UI.getIcon(targetKind + "_UNLOCK");
	if (iconURL != "") {
		return iconURL;
	} else {
		iconURL = UI.getIconURL(targetType);
		if (iconURL != "") {
			return iconURL;
		}
	}

	if (targetKind == "KIND_MODIFIER") {
		return UI.getIconURL("MOD_GENERIC_BONUS");
	}

	console.warn("cannot get icon for unhandled targetType: ", targetType, ",  target kind: ", targetKind);
	return UI.getIconURL("MOD_GENERIC_BONUS");
}

/**
 * Collect yield changes for a constructible.
 */
function collectConstructibleYields(constructibleType: string): UnlockYieldChange[] {
	const yields: UnlockYieldChange[] = [];
	for (const entry of GameInfo.Constructible_YieldChanges) {
		if (entry.ConstructibleType === constructibleType) {
			yields.push({
				yieldType: entry.YieldType,
				amount: entry.YieldChange,
			});
		}
	}
	return yields;
}

/**
 * Build adjacency list markup for a group of adjacencies.
 */
function buildAdjacencyListMarkup(entries: Adjacency_YieldChangeDefinition[]): string {
	const items = entries.map((def) => `[LI] ${parseConstructibleAdjacencyNameOnly(def)}`).join("");
	return `[BLIST]${items}[/BLIST]`;
}

/**
 * Collect adjacency groups for a constructible.
 */
function collectConstructibleAdjacencies(constructibleType: string): UnlockAdjacencyGroup[] {
	const adjacencyDefinitions: Adjacency_YieldChangeDefinition[] = [];

	for (const definition of GameInfo.Constructible_Adjacencies) {
		if (definition.ConstructibleType !== constructibleType) {
			continue;
		}
		const yieldChangeDef = GameInfo.Adjacency_YieldChanges.find((entry) => entry.ID === definition.YieldChangeId);
		if (yieldChangeDef) {
			// Skip adjacencies requiring activation when we don't have city context
			if (!definition.RequiresActivation) {
				adjacencyDefinitions.push(yieldChangeDef);
			}
		}
	}

	if (adjacencyDefinitions.length === 0) {
		return [];
	}

	const groups: UnlockAdjacencyGroup[] = [];
	let counter = 0;

	for (const yieldDefinition of GameInfo.Yields) {
		const perChangeMap = new Map<number, Adjacency_YieldChangeDefinition[]>();

		for (const changeDefinition of adjacencyDefinitions) {
			if (changeDefinition.YieldType !== yieldDefinition.YieldType) {
				continue;
			}
			const list = perChangeMap.get(changeDefinition.YieldChange);
			if (list) {
				list.push(changeDefinition);
			} else {
				perChangeMap.set(changeDefinition.YieldChange, [changeDefinition]);
			}
		}

		perChangeMap.forEach((definitions, value) => {
			const id = `${yieldDefinition.YieldType}-${value}-${counter}`;
			counter += 1;

			if (definitions.length <= 1) {
				groups.push({
					id,
					textKey: "LOC_UI_ADJACENCY_INFO_OBJECT",
					args: [
						value,
						`[icon:${yieldDefinition.YieldType}]`,
						parseConstructibleAdjacencyNameOnly(definitions[0]),
					],
				});
				return;
			}

			groups.push({
				id,
				textKey: "LOC_UI_ADJACENCY_INFO_GENERIC",
				args: [value, yieldDefinition.YieldType],
				listMarkup: buildAdjacencyListMarkup(definitions),
			});
		});
	}

	return groups;
}

/**
 * Collect modifier descriptions for a constructible.
 */
function collectConstructibleModifiers(constructibleType: string): UnlockDescriptionLine[] {
	const lines: UnlockDescriptionLine[] = [];

	for (const modifier of GameInfo.ConstructibleModifiers) {
		if (modifier.ConstructibleType === constructibleType) {
			const text = getModifierTextByContext(modifier.ModifierId, "Description");
			if (text) {
				lines.push({ text });
			}
		}
	}

	return lines;
}

/**
 * Get the tooltip text for a constructible if it exists.
 */
function getConstructibleTooltip(constructibleType: string): UnlockDescriptionLine[] {
	const def = GameInfo.Constructibles.lookup(constructibleType);
	if (def?.Tooltip) {
		return [{ text: def.Tooltip }];
	}
	return [];
}

/**
 * Collect tradition modifier descriptions.
 */
function collectTraditionModifiers(traditionType: string): UnlockDescriptionLine[] {
	const lines: UnlockDescriptionLine[] = [];
	const traditionInfo = GameInfo.Traditions.lookup(traditionType);

	if (traditionInfo) {
		for (const modifier of GameInfo.TraditionModifiers) {
			if (modifier.TraditionType === traditionInfo.TraditionType) {
				const modifierDesc = getModifierTextByContext(modifier.ModifierId, "Description");
				if (modifierDesc) {
					lines.push({ text: modifierDesc });
				}
			}
		}

		// Fall back to tradition description if no modifier descriptions
		if (lines.length === 0 && traditionInfo.Description) {
			lines.push({ text: traditionInfo.Description });
		}

		if (traditionInfo.ObsoletesTraditionType) {
			const obsoleteTradition = GameInfo.Traditions.lookup(traditionInfo.ObsoletesTraditionType);
			if (obsoleteTradition) {
				lines.push({ text: Locale.compose("LOC_CIVIC_REPLACEMENT_NAME", obsoleteTradition.Name) });
			}
		}
	}

	return lines;
}

/**
 * Get structured description data for an unlock target.
 * This returns raw localization keys and structured data suitable for
 * reactive rendering with L10n components.
 *
 * @param targetType - The type identifier of the unlock target.
 * @param targetKind - The kind of the unlock target.
 * @returns Structured description data for the unlock target.
 */
export function getUnlockTargetDescriptionData(targetType: string, targetKind: string): UnlockTargetDescription {
	const result: UnlockTargetDescription = {
		kind: targetKind,
		type: targetType,
		tags: [],
		yields: [],
		adjacencies: [],
		descriptionLines: [],
	};

	if (targetKind === "KIND_MODIFIER") {
		const modInfo = GameInfo.Modifiers.find((o) => o.ModifierId === targetType);
		if (modInfo) {
			const modifierDesc = getModifierTextByContext(modInfo.ModifierId, "Description");
			if (modifierDesc) {
				result.descriptionLines.push({ text: modifierDesc });
			}
		}
	} else if (targetKind === "KIND_CONSTRUCTIBLE") {
		// Tags
		result.tags = getConstructibleTagsFromType(targetType);

		// Yields
		result.yields = collectConstructibleYields(targetType);

		// Adjacencies
		result.adjacencies = collectConstructibleAdjacencies(targetType);

		// Modifiers first (they usually describe core functionality)
		result.descriptionLines = collectConstructibleModifiers(targetType);

		// Then tooltip text (contains additional details)
		const tooltipLines = getConstructibleTooltip(targetType);
		if (tooltipLines.length > 0) {
			// If we already have modifier descriptions, only add tooltip if different
			if (result.descriptionLines.length === 0) {
				result.descriptionLines.push(...tooltipLines);
			} else {
				// Add tooltip lines that aren't duplicates
				for (const line of tooltipLines) {
					const isDuplicate = result.descriptionLines.some((d) => d.text === line.text);
					if (!isDuplicate) {
						result.descriptionLines.push(line);
					}
				}
			}
		}

		// Collect unlocked Great People
		const playerUnits = Players.Units.get(GameContext.localPlayerID);
		if (playerUnits) {
			GameInfo.GreatPersonClasses.forEach((greatPersonClass) => {
				if (!greatPersonClass.ConstructibleType && !greatPersonClass.ConstructibleTag) return;
				if (greatPersonClass.ConstructibleType) {
					if (greatPersonClass.ConstructibleType !== targetType) return;
				}
				if (greatPersonClass.ConstructibleTag) {
					if (!ConstructibleHasTagType(targetType, greatPersonClass.ConstructibleTag)) return;
				}

				const greatPersonUnitDef = GameInfo.Units.lookup(greatPersonClass.UnitType);

				if (greatPersonUnitDef && playerUnits.canEverTrain(greatPersonClass.UnitType)) {
					const unitName = greatPersonUnitDef.Description
						? `[TIP:${greatPersonUnitDef.Description}]{${greatPersonUnitDef.Name}}[/TIP]`
						: greatPersonUnitDef.Name;

					result.descriptionLines.push({
						text: Locale.compose(
							"LOC_UI_PRODUCTION_ALLOWS_TRAINING",
							greatPersonUnitDef.UnitType,
							unitName,
						),
					});
				}
			});
		}
	} else if (targetKind === "KIND_UNIT") {
		const unitInfo = GameInfo.Units.find((o) => o.UnitType === targetType);
		if (unitInfo?.Description) {
			result.descriptionLines.push({ text: unitInfo.Description });
		}
	} else if (targetKind === "KIND_TRADITION") {
		result.descriptionLines = collectTraditionModifiers(targetType);
	} else if (targetKind === "KIND_DIPLOMATIC_ACTION") {
		const diploActionInfo = GameInfo.DiplomacyActions.find((o) => o.DiplomacyActionType === targetType);
		if (diploActionInfo?.Description) {
			result.descriptionLines.push({ text: diploActionInfo.Description });
		}
	} else if (targetKind === "KIND_PROJECT") {
		const projectInfo = GameInfo.Projects.find((o) => o.ProjectType === targetType);
		if (projectInfo?.Description) {
			result.descriptionLines.push({ text: projectInfo.Description });
		}
	}

	return result;
}

/**
 * Check if an unlock target has meaningful description content.
 * @param data - The unlock target description data.
 * @returns True if there is content to display.
 */
export function hasUnlockContent(data: UnlockTargetDescription): boolean {
	return (
		data.tags.length > 0 ||
		data.yields.length > 0 ||
		data.adjacencies.length > 0 ||
		data.descriptionLines.length > 0
	);
}

/**
 * Extended unlock display data with structured description information.
 * This extends the base NodeUnlockDisplayData with additional fields for
 * reactive rendering.
 */
export interface UnlockDisplayData {
	/** Icon URL for the unlock. */
	icon: string;
	/** Localization key for the name. */
	nameKey: string;
	/** Target kind (e.g., "KIND_UNIT", "KIND_CONSTRUCTIBLE"). */
	kind: string;
	/** Target type identifier. */
	type: string;
	/** Depth level at which this unlock occurs. */
	depth: number;
	/** Structured description data for rich rendering. */
	descriptionData: UnlockTargetDescription;
}

/**
 * Depth info structure compatible with existing TreeGridDepthInfo but
 * using the new UnlockDisplayData for richer unlock information.
 */
export interface ChooserDepthInfo {
	/** Header text (usually empty in choosers). */
	header: string;
	/** Array of unlock items with structured data. */
	unlocks: UnlockDisplayData[];
	/** Whether this depth level has been completed. */
	isCompleted: boolean;
	/** Whether this depth level is currently being researched. */
	isCurrent: boolean;
	/** Whether this depth level is locked. */
	isLocked: boolean;
}

/**
 * Build unlock display data for a single progression tree node unlock.
 * @param unlockInfo - The raw unlock info from GameInfo.
 * @returns Structured unlock display data.
 */
export function buildUnlockDisplayData(unlockInfo: ProgressionTreeNodeUnlockDefinition): UnlockDisplayData {
	const nameKey = getUnlockTargetNameKey(unlockInfo.TargetType, unlockInfo.TargetKind);
	const icon = getUnlockTargetIconUrl(unlockInfo.TargetType, unlockInfo.TargetKind);
	const descriptionData = getUnlockTargetDescriptionData(unlockInfo.TargetType, unlockInfo.TargetKind);

	return {
		icon,
		nameKey,
		kind: unlockInfo.TargetKind,
		type: unlockInfo.TargetType,
		depth: unlockInfo.UnlockDepth,
		descriptionData,
	};
}

/**
 * Convert a legacy NodeUnlockDisplayData to the new UnlockDisplayData format.
 * This allows existing code that uses the old API to work with the new tooltip components.
 * @param legacyUnlock - The legacy unlock data.
 * @returns The new format unlock display data.
 */
export function convertLegacyUnlock(legacyUnlock: NodeUnlockDisplayData): UnlockDisplayData {
	const descriptionData = getUnlockTargetDescriptionData(String(legacyUnlock.type), legacyUnlock.kind);

	return {
		icon: legacyUnlock.icon,
		nameKey: legacyUnlock.name,
		kind: legacyUnlock.kind,
		type: String(legacyUnlock.type),
		depth: legacyUnlock.depth,
		descriptionData,
	};
}

/**
 * Convert legacy TreeGridDepthInfo array to the new ChooserDepthInfo format.
 * This is useful when consuming data from legacy APIs that produce TreeGridDepthInfo.
 * @param legacyDepths - Array of legacy TreeGridDepthInfo objects.
 * @returns Array of ChooserDepthInfo objects with structured unlock data.
 */
export function convertLegacyDepthInfo(legacyDepths: TreeGridDepthInfo[]): ChooserDepthInfo[] {
	return legacyDepths.map((depth) => ({
		header: depth.header,
		unlocks: depth.unlocks.map(convertLegacyUnlock),
		isCompleted: depth.isCompleted,
		isCurrent: depth.isCurrent,
		isLocked: depth.isLocked,
	}));
}
